VALUES (64690, 'tt0780504', NULL, 'Drive', 'Drive', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/602vevIURmpDfzbnv5Ubi6wIkQm.jpg', 'https://image.tmdb.org/t/p/original/hoyAALgfmjMEK7O1wZ4r8wT91RP.jpg', 'Driver is a skilled Hollywood stuntman who moonlights as a getaway driver for criminals. Though he projects an icy exterior, lately he''s been warming up to a pretty neighbor named Irene and her young son, Benicio. When Irene''s husband gets out of jail, he enlists Driver''s help in a million-dollar heist. The job goes horribly wrong, and Driver must risk his life to protect Irene and Benicio from the vengeful masterminds behind the robbery.', NULL, NULL, 12.6264, 7.582, 0, 8.51619753086419706e+01, '2026-07-15 12:01:52', '2026-11-07 15:15:25')
