VALUES (9392, 'tt0435625', NULL, 'The Descent', 'The Descent', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/mxFPI4KYBk5ri9cPteIS8jiDFgj.jpg', 'https://image.tmdb.org/t/p/original/9T5D5RGuCsC6CeqYZJTv4rT4RPy.jpg', 'After a personal tragedy, Sarah joins her friends on a caving expedition in the Appalachian Mountains. But when a rockfall traps them deep underground, their adventure turns into a nightmare. As they search for a way out, the group discovers they are not alone—lurking in the darkness are savage, cave-dwelling creatures. With rising tension and dwindling trust, the women must fight to survive against both the predators and each other.', NULL, NULL, 10.3074, 6.99, 0, 5.13022916666666617e+01, '2026-07-15 12:01:52', '2026-11-07 15:15:25')
