VALUES (NULL, NULL, 1877, 'Cyberpunk 2077', 'Cyberpunk 2077', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaih8.jpg', NULL, 'Cyberpunk 2077 is an open-world action-adventure game set in Night City, a sprawling metropolis driven by power, glamour, and body modification. Players assume the role of V, a mercenary outlaw in pursuit of a unique implant that holds the key to immortality. The game allows extensive customization of cyberware, skills, and playstyle. Choices made throughout the journey influence both the narrative and the world.', 'https://www.igdb.com/games/cyberpunk-2077', '["Google Stadia", "Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One"]', NULL, NULL, 0, 13.526, '2026-07-15 12:01:52', '2026-11-07 15:15:25')
