VALUES (49730, 'tt1486185', NULL, 'Red Riding Hood', 'Red Riding Hood', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/ixQYkLeLlTTnAoT32dukndyObB6.jpg', 'https://image.tmdb.org/t/p/original/r4A5SQSGTfleodMm45w7MJgE2WF.jpg', 'Valerie is in love with a brooding outsider, Peter, but her parents have arranged for her to marry another man. Unwilling to lose each other, Valerie and Peter plan to run away together when Valerie''s older sister is killed by a werewolf that prowls the dark forest surrounding their village. Panic grips the town as Valerie discovers that she has a unique connection to the beast--one that inexorably draws them together, making her both suspect ... and bait.', NULL, NULL, 5.4914, 5.975, 0, 1.84536363636363631e+01, '2026-07-15 12:01:52', '2026-11-07 15:15:25')
