VALUES (34647, 'tt1191111', NULL, 'Enter the Void', 'Enter the Void', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/krKnsfvSJM1PL40tLicRhVQ6kuG.jpg', 'https://image.tmdb.org/t/p/original/2Mlw0JRNZHXLYxbeJ0LmiCCTiok.jpg', 'This psychedelic tour of life after death is seen entirely from the point of view of Oscar, a young American drug dealer and addict living in Tokyo with his prostitute sister, Linda. When Oscar is killed by police during a bust gone bad, his spirit journeys from the past -- where he sees his parents before their deaths -- to the present -- where he witnesses his own autopsy -- and then to the future, where he looks out for his sister from beyond the grave.', NULL, NULL, 3.251, 7.269, 0, 174.825, '2026-07-15 12:01:52', '2026-11-07 15:15:25')
