VALUES (11023, 'tt0328538', NULL, 'Thirteen', 'Thirteen', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/uzTLlZrNF6rMPBh5mUQu6vLnTtX.jpg', 'https://image.tmdb.org/t/p/original/ow2boWFZWza7D4qDvJohg9GJVoH.jpg', 'When 13-year-old Tracy befriends Evie, the most popular girl in school, her life is turned upside down as Evie introduces her to a world of sex, drugs, and money. But it isn’t long before Tracy’s new lifestyle begins to take a heavy toll on her and her family.', NULL, NULL, 4.4338, 6.691, 0, 8.17976923076923156e+01, '2026-07-15 12:01:52', '2026-11-07 15:15:25')
