VALUES (120467, 'tt2278388', NULL, 'The Grand Budapest Hotel', 'The Grand Budapest Hotel', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/eWdyYQreja6JGCzqHWXpWHDrrPo.jpg', 'https://image.tmdb.org/t/p/original/jK65srQczOKTpW62wPxwwKztGgE.jpg', 'The Grand Budapest Hotel tells of a legendary concierge at a famous European hotel between the wars and his friendship with a young employee who becomes his trusted protégé. The story involves the theft and recovery of a priceless Renaissance painting, the battle for an enormous family fortune and the slow and then sudden upheavals that transformed Europe during the first half of the 20th century.', NULL, NULL, 25.9231, 8.027, 0, 5.52583673469387761e+01, '2026-07-15 12:01:52', '2026-11-07 15:15:25')
