VALUES (10451, 'tt0111797', NULL, 'Eat Drink Man Woman', '飲食男女', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/olhIWtIBFg6VWK59DEd4lAvgVgz.jpg', 'https://image.tmdb.org/t/p/original/tllmUjmEQKF0OaH7FgqZYnLBsYB.jpg', 'Retired and widowed Chinese master chef Chu lives in modern day Taipei, with his three attractive daughters, all of whom are unattached. Soon, each daughter encounters a new man in their lives. When these new relationships blossom, stereotypes are broken and the living situation within the family changes.', NULL, NULL, 4.4039, 7.619, 0, 7.67666666666666586e+00, '2026-07-20 01:02:04', '2026-11-07 15:15:25')
