VALUES (20048, 'tt1093908', NULL, 'Confessions of a Shopaholic', 'Confessions of a Shopaholic', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/r17R9OIC0pKDqqsNore6atYLCVZ.jpg', 'https://image.tmdb.org/t/p/original/vTMM4QXG6Jye7yffsOpz24oPNg1.jpg', 'In the glamorous world of New York City, Rebecca Bloomwood is a fun-loving girl who is really good at shopping – a little too good, perhaps. She dreams of working for her favorite fashion magazine, but can''t quite get her foot in the door – until ironically, she snags a job as an advice columnist for a financial magazine published by the same company.', NULL, NULL, 6.7256, 6.488, 0, 16.25, '2026-07-21 03:32:24', '2026-11-07 15:15:25')
