VALUES (37233, 'tt0106918', NULL, 'The Firm', 'The Firm', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/kFexXCzidkm4LwlgZqxsJsDQB5v.jpg', 'https://image.tmdb.org/t/p/original/jlUTfePS1XRyMpgZvjFvDk7yEi0.jpg', 'Mitch McDeere is a young man with a promising future in Law. About to sit his Bar exam, he is approached by ''The Firm'' and made an offer he doesn''t refuse. Seduced by the money and gifts showered on him, he is totally oblivious to the more sinister side of his company. Then, two Associates are murdered. The FBI contact him, asking him for information and suddenly his life is ruined. He has a choice - work with the FBI, or stay with the Firm. Either way he will lose his life as he knows it. Mitch figures the only way out is to follow his own plan...', NULL, NULL, 5.0694, 6.748, 0, 11.02625, '2026-08-08 02:23:49', '2026-11-07 15:15:25')
