VALUES (648, 'tt0038348', NULL, 'Beauty and the Beast', 'La Belle et la Bête', 'movie', 1946, 'https://image.tmdb.org/t/p/w500/iYSe3yrkma0e1B0wWPXgr8w5sDN.jpg', 'https://image.tmdb.org/t/p/original/2Ae0iV2HR3Raoras8G40MjBtJnn.jpg', 'The story of a gentle-hearted beast in love with a simple and beautiful girl. She is drawn to the repellent but strangely fascinating Beast, who tests her fidelity by giving her a key, telling her that if she doesn''t return it to him by a specific time, he will die of grief. She is unable to return the key on time, but it is revealed that the Beast is the genuinely handsome one. A simple tale of tragic love that turns into a surreal vision of death, desire, and beauty.', NULL, NULL, 3.8102, 7.501, 0, 1.20300000000000011e+01, '2026-08-11 02:46:38', '2026-11-07 15:15:25')
