VALUES (11975, 'tt0119978', NULL, 'The Rainmaker', 'The Rainmaker', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/twLGHXPjQtS8UyVGp5GXmhJiTM7.jpg', 'https://image.tmdb.org/t/p/original/v0IeACcCsKLKqT4eCJsZ60nySQL.jpg', 'Fresh out of law school and desperate for work, idealistic rookie Rudy Baylor takes on a powerful insurance company accused of denying a dying boy’s claim. Teaming up with a scrappy, unlicensed paralegal, he finds himself in a David-versus-Goliath courtroom battle that tests his ethics, courage, and belief in justice.', NULL, NULL, 5.1994, 7.0, 0, 2.01, '2026-10-21 05:03:47', '2026-11-07 15:15:25')
